-- Reference configuration only. No legacy accounts, wallets, events or grants.
create table public.gift_categories (
 id text primary key, label text not null, sort_order integer not null,
 enabled boolean not null default true
);
create table public.cp_types (
 id text primary key check (id ~ '^[a-z][a-z0-9_]{0,39}$'),
 label text not null check (char_length(label) between 1 and 80),
 enabled boolean not null default false, is_primary boolean not null default false,
 presentation jsonb not null default '{}' check (jsonb_typeof(presentation)='object'),
 level_thresholds bigint[] not null default '{}'
);
create unique index cp_types_one_primary on public.cp_types (is_primary) where is_primary;
create table public.gift_catalog (
 id text primary key, name text not null, price bigint not null check (price>0),
 is_active boolean not null default true,
 diamond_source_type text not null check (diamond_source_type in ('FIXED_GIFT','LUCKY_GIFT')),
 global_announcement_enabled boolean not null default false,
 category_id text not null default 'gift' references public.gift_categories(id),
 relationship_type_id text references public.cp_types(id),
 icon text not null default '🎁', description text not null default '',
 preview_url text check (preview_url is null or preview_url like 'https://%' or preview_url like '/%'),
 animation_type text not null default 'sparkle' check (animation_type in ('pulse','rocket','lion','car','crown','sparkle')),
 rarity text, duration_days integer check (duration_days between 1 and 365),
 check ((category_id='cp')=(relationship_type_id is not null))
);
create table public.store_catalog (
 id text primary key, name text not null,
 category text not null check (category in ('frames','cars','bubbles','badges','vip','entrances','cards')),
 price bigint not null check (price>0),
 currency text not null check (currency in ('gold','silver')),
 icon text not null default '🎁', description text not null default '',
 duration_days integer check (duration_days between 1 and 365),
 vip_level integer check (vip_level between 1 and 10),
 is_active boolean not null default true, is_reward boolean not null default false,
 relationship_type_id text references public.cp_types(id),
 presentation jsonb not null default '{}' check (jsonb_typeof(presentation)='object'),
 preview_url text check (preview_url is null or preview_url like 'https://%' or preview_url like '/%'),
 check ((category='cards')=(relationship_type_id is not null))
);
create table public.recharge_packages (
 id uuid primary key default gen_random_uuid(),
 price_usd numeric not null unique check (price_usd>0 and price_usd<=100),
 gold_amount bigint not null check (gold_amount>0),
 is_active boolean not null default true,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.recharge_reward_tiers (
 id text primary key, label text not null,
 threshold_usd numeric not null check (threshold_usd>0),
 rewards jsonb not null check (jsonb_typeof(rewards)='array')
);
create index gift_catalog_category_idx on public.gift_catalog(category_id);
create index gift_catalog_relationship_idx on public.gift_catalog(relationship_type_id);
create index store_catalog_relationship_idx on public.store_catalog(relationship_type_id);

insert into public.gift_categories (id,label,enabled,sort_order)
select id,label,enabled,sort_order from jsonb_populate_recordset(null::public.gift_categories, '[{"id":"cp","label":"CP","enabled":true,"sort_order":30},{"id":"custom","label":"مخصص","enabled":true,"sort_order":20},{"id":"gift","label":"هدية","enabled":true,"sort_order":50},{"id":"luck","label":"حظ","enabled":true,"sort_order":10},{"id":"nation","label":"الأمة","enabled":true,"sort_order":40}]'::jsonb);
alter table public.gift_categories enable row level security;
revoke all on public.gift_categories from PUBLIC, anon, authenticated;
grant select on public.gift_categories to authenticated;
grant all on public.gift_categories to service_role;
create policy catalog_read on public.gift_categories for select to authenticated using (enabled);
comment on table public.gift_categories is 'Reference configuration imported from legacy; no operational records or client writes. Financial execution remains separate.';

